script:
card({ name: "Turn order", icon: 'shuffle' });
const words = {
  addMe: "Add me",
  addName: "Add a name",
  shuffle: "Shuffle",
  clear: "Clear",
  empty: "Add names, then shuffle",
  by: "Shuffled by {p0}",
  full: "Twenty names at most",
  twice: "{p0} is already on the list",
};

// Names in a fair order. ctx.random() shuffles the same way on every phone.
function init() {
  return { names: [], shuffled: false, by: '' };
}

function add(s, name) {
  name = String(name || '').trim().slice(0, 40);
  if (!name) return;
  if (s.names.includes(name)) throw words.twice.replace('{p0}', name);
  if (s.names.length >= 20) throw words.full;
  s.names.push(name);
  s.shuffled = false;
}

on.join = (s, args, ctx) => add(s, ctx.authorName);
on.add = (s, args) => add(s, args.value);

on.shuffle = (s, args, ctx) => {
  const n = s.names;
  for (let i = n.length - 1; i > 0; i--) {
    const j = Math.floor(ctx.random() * (i + 1));
    const t = n[i];
    n[i] = n[j];
    n[j] = t;
  }
  s.shuffled = true;
  s.by = ctx.authorName;
};

on.clear = (s) => init();

function view(s) {
  const parts = [];
  if (!s.names.length) parts.push(text(words.empty, { tone: 'muted' }));
  s.names.forEach((name, i) => {
    parts.push(text((s.shuffled ? (i + 1) + '. ' : '• ') + name, { bold: s.shuffled && i === 0, tone: s.shuffled && i === 0 ? 'accent' : undefined }));
  });
  if (s.shuffled) parts.push(text(words.by.replace('{p0}', s.by), { size: 'small', tone: 'muted' }));
  parts.push(input('name', words.addName, 'add'));
  parts.push(row([
    button(words.addMe, 'join'),
    button('🔀 ' + words.shuffle, 'shuffle', null, { tone: 'accent' }),
    button(words.clear, 'clear', null, { tone: 'muted' }),
  ]));
  return column(parts);
}
